 dict(kind="table", head="अंधविश्वास और विज्ञान", eq="सोचिए, परखिए",
      rows=[["मान्यता", "सच्चाई"], ["बुख़ार = नज़र लगना", "कीटाणु/विषाणु से संक्रमण — जाँच और दवा"], ["सर्पदंश में झाड़-फूँक", "तुरंत अस्पताल; सही इलाज = एंटी-वेनम"], ["ग्रहण अशुभ", "सूर्य, चंद्र, पृथ्वी की स्थिति — प्राकृतिक घटना (बस सीधे सूर्य को न देखें)"], ["चेचक = देवी का प्रकोप", "वायरस का रोग — टीके से दुनिया से ख़त्म"], ["कुएँ का पानी अपने-आप शुद्ध", "उबालें/छानें — हैजा, टाइफ़ॉइड से बचाव"]],
      say="कुछ उदाहरण देखिए। बुख़ार को, नज़र लगना मानते हैं, पर सच ये है, कि बुख़ार, कीटाणु या विषाणु के, संक्रमण से होता है, इसलिए, जाँच और दवा। साँप काटे, तो झाड़-फूँक में, समय बर्बाद न करें, तुरंत अस्पताल जाएँ, जहाँ, एंटी-वेनम से, सही इलाज होता है। बिहार में, हर साल, कई जानें, इसी देरी से जाती हैं। ग्रहण, सूर्य, चंद्रमा, और पृथ्वी की, स्थिति से बनने वाली, प्राकृतिक घटना है, बस, सूरज को, सीधे आँखों से न देखें। चेचक को, कभी, देवी का प्रकोप मानते थे, पर वो, वायरस का रोग था, जिसे, टीके ने, पूरी दुनिया से, ख़त्म कर दिया। और कुएँ का पानी, उबालकर पिएँ, ताकि, हैजा और टाइफ़ॉइड से बचें।"),

